#!/usr/bin/env node
/* One-off targeted bundle build for fe/data-receipt (2026-10-07).
   Builds ONLY the two bundles this change touches, mirroring
   build/bundle.js + build/bundle-core.js concat/terser/validate logic —
   so sibling uncommitted sources never bake into unrelated bundles.
   Bundles: games/bundle-receipt.js, pages/bundle-pages.js
   Run from the repo root: node scripts/build-receipt-bundles.js */
'use strict';
var fs = require('fs');
var path = require('path');
var cp = require('child_process');

var ROOT = path.join(__dirname, '..');
var V143 = path.join(ROOT, 'v1.4.3');

function gameFiles(name) {
  var src = fs.readFileSync(path.join(ROOT, 'build', 'bundle.js'), 'utf8');
  var idx = src.indexOf("'" + name + "'");
  if (idx < 0) throw new Error('bundle entry not found: ' + name);
  var end = src.indexOf('],', idx);
  if (end < 0) throw new Error('bundle entry unterminated: ' + name);
  var block = src.slice(idx, end);
  var files = [];
  var re = /'(\.\.\/)?([a-z0-9-]+\.js)'/g, m;
  while ((m = re.exec(block))) {
    var f = (m[1] || '') + m[2];
    if (m[2] !== name + '.js' && files.indexOf(f) === -1) files.push(f);
  }
  return files;
}
function coreFiles(name) {
  var src = fs.readFileSync(path.join(ROOT, 'build', 'bundle-core.js'), 'utf8');
  var idx = src.indexOf("'" + name + "'");
  if (idx < 0) throw new Error('bundle entry not found: ' + name);
  idx = src.indexOf('[', idx);
  var end = src.indexOf('],', idx);
  if (end < 0) throw new Error('bundle entry unterminated: ' + name);
  var block = src.slice(idx, end);
  var files = [];
  var re = /'([a-z0-9\-\/]+\.js)'/g, m;
  while ((m = re.exec(block))) {
    if (files.indexOf(m[1]) === -1) files.push(m[1]);
  }
  return files;
}

var TERSER = null;
try { cp.execSync('which terser', { stdio: 'pipe' }); TERSER = 'terser'; }
catch (e) { console.error('BUNDLE WARN: no terser — writing raw.'); }

function build(name, dir, files, header, prefixDir) {
  var out = [];
  out.push('/* PF v1.4.3 ' + name + '.js — concatenated bundle. DO NOT EDIT.');
  out.push('   ' + header);
  out.push('   Contains: ' + files.join(', ') + ' */');
  files.forEach(function (f) {
    /* coreFiles entries already carry their subdir (pages/..., core/...);
       gameFiles entries are bare filenames under games/. */
    var p = prefixDir ? path.join(V143, dir, f) : path.join(V143, f);
    if (!fs.existsSync(p)) throw new Error('missing file: ' + f);
    out.push('\n/* ===== ' + f + ' ===== */');
    out.push(fs.readFileSync(p, 'utf8'));
    out.push(';');
  });
  var dest = path.join(V143, dir, name + '.js');
  var raw = out.join('\n');
  var final = raw;
  if (TERSER) {
    try {
      final = cp.execSync(TERSER + ' --compress --mangle --toplevel', {
        input: raw, maxBuffer: 100 * 1024 * 1024
      }).toString();
    } catch (e) {
      console.error('BUNDLE WARN: terser failed on ' + name + ' — writing raw.');
      final = raw;
    }
  }
  fs.writeFileSync(dest, final);
  cp.execSync('node --check ' + dest, { stdio: 'pipe' });
  new Function(fs.readFileSync(dest, 'utf8'));
  var kb = (fs.statSync(dest).size / 1024).toFixed(1);
  console.log(name + '.js: ' + files.length + ' files, ' + kb + ' KB — OK');
}

build('bundle-receipt', 'games', gameFiles('bundle-receipt'),
  'THE RECEIPT (fe/data-receipt). Generated by scripts/build-receipt-bundles.js.', true);
build('bundle-pages', 'pages', coreFiles('pages/bundle-pages'),
  'Regenerated by scripts/build-receipt-bundles.js (page-mount.js: pf-receipt entry).', false);
console.log('Receipt bundles built and validated.');
